    ('get them both out to the wall itself, and argue it there in the open', 'R1', None, 0.45, '', {'v': 'stimulation, self-direction', 'aim': 'try', 'chance': 0.5}),
    ('let it lie this year, and wait until the two of them soften', 'G1', None, 0.45, '', {'v': 'security, tradition', 'aim': 'skip', 'chance': 0.88}),
    ('write down both stories first, then decide by what can be shown', 'W1', 'U.7', 0.5, '', {'v': 'conformity, self-direction', 'aim': 'try', 'chance': 0.65}),
    ('find what each one wants more than the foot of ground', 'U1', 'B.7', 0.5, '', {'v': 'self-direction, achievement', 'aim': 'try', 'chance': 0.6}),
