    ('take a fortnight off the counting, and come back with fresh eyes', 'G1', None, 0.45, '', {'v': 'security, tradition', 'aim': 'ease', 'chance': 0.88}),
    ('write up the method in full, so anyone could check the count', 'W1', 'U.7', 0.5, '', {'v': 'conformity, self-direction', 'aim': 'work', 'chance': 0.75}),
