{'name': 'the sea walls on the east coast',
 'stages': 'adult mature elder',
 'age': (30, 90),
 'alpha': 'W.2 U.2 B.2 R.2 G.2',
 'stakes': 1.0,
 'rate': 0.0,
 'tier': 'decision',
 'tone': 'trouble',
 'life': 'home, community',
 'horizon': 'years',
 'roles': 'colleague, rival, elder',
 'scope': 'nation',
 'cast_want': 'decide',
 'sphere': 'prot',
 'worlds': {'earth': 'the sea walls along the coast are old and the money will mend half of them, and {N} decides '
                     'which'},
 'scenes': {'earth': [('',
                       'The sea walls along the east coast were built by the grandparents of the people behind them, '
                       'and the last storm opened three of them. The money in the budget will mend half the walls at '
                       'most. The coastal towns, the farmers on the low fields and the engineers all have a plan, '
                       'and the choice is {Ns}.')]},
 'outcomes': (["The next winter's storms come and go, and the walls and the marsh both hold.",
               '{elder}, who has farmed the low fields all a long life, says the plan was hard but right.'],
              ['A stretch of coast left for later floods in the spring, and the families there want to know why.',
               '{rival} says the plan picked winners and losers along the coast, and the losers agree.']),
 'options': [
    ('mend the walls the flood models say protect the most homes', 'U1', None, 0.45, '', {'v': 'achievement, security', 'scope': 'nation', 'lever': 'lead', 'chance': 0.6}),
    ('let the lowest fields go back to salt marsh, which holds the sea better than walls', 'G1', None, 0.45, '', {'v': 'universalism, security', 'scope': 'nation', 'lever': 'found', 'chance': 0.55}),
    ('mend every wall a little, so that no stretch of coast is left out', 'W1', None, 0.45, '', {'v': 'universalism, conformity', 'scope': 'nation', 'lever': 'loyalty', 'chance': 0.55}),
    ('mend first the walls of the towns that pay half the cost', 'B1', None, 0.45, '', {'v': 'power, security', 'scope': 'nation', 'lever': 'fund', 'chance': 0.6}),
 ]},
