    ('propose closing the river entirely for one summer, and argue it at the meeting', 'R1', None, 0.45, '', {'v': 'stimulation, universalism', 'aim': 'work', 'chance': 0.55}),
    ("hand the settlement to the users' own keepers, and step away from the table", 'G1', None, 0.45, '', {'v': 'benevolence, tradition', 'aim': 'stop', 'chance': 0.8}),
    ('keep equal days, but let the counts decide each year how many days there are', 'W1', 'U.7', 0.5, '', {'v': 'conformity, self-direction', 'aim': 'work', 'chance': 0.7}),
    ('ask the farm to fund a weir that keeps the water up, for its days', 'U1', 'B.7', 0.5, '', {'v': 'self-direction, power', 'aim': 'work', 'chance': 0.61}),
    ('let the users quarrel openly again for a season, if that is what it takes', 'B1', 'R.7', 0.5, '', {'v': 'power, stimulation', 'aim': 'ease', 'chance': 0.65}),
