    ('invite the critics who matter, and make sure they see the best of it', 'B1', None, 0.45, '', {'v': 'power, achievement', 'aim': 'work', 'chance': 0.63}),
    ('try the most daring version first, and let the room react however it reacts', 'R1', None, 0.45, '', {'v': 'stimulation, hedonism', 'aim': 'work', 'chance': 0.6}),
    ('keep the nights small, for the regulars, and never let them become a spectacle', 'G1', None, 0.45, '', {'v': 'tradition, benevolence', 'aim': 'ease', 'chance': 0.77}),
    ("publish the nights' results each month, and let them build a reputation", 'W1', 'B.7', 0.5, '', {'v': 'conformity, achievement', 'aim': 'work', 'chance': 0.65}),
    ('let the audience choose which untried idea gets tested next', 'U1', 'R.7', 0.5, '', {'v': 'self-direction, stimulation', 'aim': 'work', 'chance': 0.65}),
    ('bring in a newcomer each month to try their own work beside {Ns}', 'B1', 'G.7', 0.5, '', {'v': 'achievement, benevolence', 'aim': 'work', 'chance': 0.73}),
